"""Original end-to-end teaching states, not observed OS traces or platform ABI."""

def scene(identifier, title, intro, assumptions, nodes, edges, steps, marker):
    keys=[x[0] for x in nodes]
    result=[]
    for row in steps:
        heading,explanation,actor,focus,active,values,fields=row
        assert len(values)==len(keys)
        result.append(dict(title=heading,explanation=explanation,actor=actor,
                           focus=focus,active=active,states=dict(zip(keys,values)),
                           fields=[dict(name=n,before=b,after=a,why=w) for n,b,a,w in fields],
                           bands=[dict(label=n,value=a,detail=w) for n,b,a,w in fields]))
    return dict(id=identifier,volume='operating-systems',chapter='os-35-end-to-end',
                anchor='os-35-end-to-end',title=title,intro=intro,assumptions=assumptions,
                nodes=[dict(id=k,label=l,sub=s) for k,l,s in nodes],
                edges=[dict(id=k,**{'from':a,'to':b},label=l) for k,a,b,l in edges],
                steps=result,insert_before=marker)

