def shown(value):
    return 'ещё не получено' if value is None else str(value)

normal_rows=[]
for i,(state,description) in enumerate(zip(NORMAL_STATES,_NORMAL_TEXT)):
    title,explanation,actor,focus,active,cpu=description
    previous=NORMAL_STATES[max(0,i-1)]
    values=[('результат ещё не получен' if state['buffer'] is None else shown(state['buffer'])+' в VA 0x00403124'),cpu,
            ('не открыто' if state['offset'] is None else '3→O1→inode 7; offset '+str(state['offset'])),
            str(state['cache'])+(' / изменён' if state['dirty'] else ' / согласован'),
            'подтверждено '+str(state['durable']),
            'получено '+str(state['received'])+'/4; '+('результат неизвестен' if state['client_result'] is None else 'R17 → '+str(state['client_result']))]
    fields=[('Буфер / кэш / устойчивое',shown(previous['buffer'])+' / '+str(previous['cache'])+' / '+str(previous['durable']),
             shown(state['buffer'])+' / '+str(state['cache'])+' / '+str(state['durable']),explanation),
            ('Текущая позиция O1',str(previous['offset']) if previous['offset'] is not None else 'открытия нет',
             str(state['offset']) if state['offset'] is not None else 'открытия нет','Позиция относится к O1; pwrite задаёт отдельное смещение.')]
    normal_rows.append((title,explanation,actor,focus,active,values,fields))

